start_y = y;
x += args[0];
y += args[1];
cff_builder_add_point( builder, x, y, 0 );
x += args[2];
y += args[3];
cff_builder_add_point( builder, x, y, 0 );
x += args[4];
cff_builder_add_point( builder, x, y, 1 );
x += args[5];
cff_builder_add_point( builder, x, y, 0 );
x += args[6];
y += args[7];
cff_builder_add_point( builder, x, y, 0 );
x += args[8];
y  = start_y;
cff_builder_add_point( builder, x, y, 1 );
args = stack;
