}
case cff_op_hflex:
{
FT_Pos start_y;
FT_TRACE4(( " hflex\n" ));
if ( cff_builder_start_point( builder, x, y ) ||
check_points( builder, 6 )               )
goto Fail;
start_y = y;
x += args[0];
cff_builder_add_point( builder, x, y, 0 );
x += args[1];
y += args[2];
cff_builder_add_point( builder, x, y, 0 );
x += args[3];
cff_builder_add_point( builder, x, y, 1 );
x += args[4];
cff_builder_add_point( builder, x, y, 0 );
x += args[5];
y  = start_y;
cff_builder_add_point( builder, x, y, 0 );
x += args[6];
cff_builder_add_point( builder, x, y, 1 );
args = stack;
break;
}
