{
FT_Pos     start_x, start_y;
FT_Fixed   dx = 0, dy = 0;
FT_Int     horizontal, count;
FT_Fixed*  temp;
FT_TRACE4(( " flex1\n" ));
if ( cff_builder_start_point( builder, x, y ) ||
check_points( builder, 6 )               )
goto Fail;
start_x = x;
start_y = y;
temp = args;
for ( count = 5; count > 0; count-- )
{
dx += temp[0];
dy += temp[1];
temp += 2;
}
if ( dx < 0 )
dx = -dx;
if ( dy < 0 )
dy = -dy;
horizontal = ( dx > dy );
for ( count = 5; count > 0; count-- )
{
x += args[0];
y += args[1];
cff_builder_add_point( builder, x, y,
(FT_Bool)( count == 3 ) );
args += 2;
}
if ( horizontal )
{
x += args[0];
y  = start_y;
}
else
{
x  = start_x;
y += args[0];
}
cff_builder_add_point( builder, x, y, 1 );
args = stack;
break;
}
case cff_op_flex:
{
FT_UInt  count;
FT_TRACE4(( " flex\n" ));
if ( cff_builder_start_point( builder, x, y ) ||
check_points( builder, 6 )               )
goto Fail;
for ( count = 6; count > 0; count-- )
{
x += args[0];
y += args[1];
cff_builder_add_point( builder, x, y,
(FT_Bool)( count == 4 || count == 1 ) );
args += 2;
}
args = stack;
